window.kbPageData["views/entry/k-259adcd221f15b69"] = {"key":"entry/k-259adcd221f15b69","state":{"route":"entry/k-259adcd221f15b69"},"node":{"id":"k-259adcd221f15b69","mode":"k","title":"关于坚持和完善人民代表大会制度的重要思想","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["观点与论证"],"出处性质":["理论手册"],"学科":["政治理论"],"来源主题":["新时代中国特色社会主义思想"],"资料类别":["非时政"]},"directorySummary":"2024 年 9 月 14 日，中共中央、全国人大常委会隆重举行庆祝全国人民代表大会成立\n70 周年大会。习近平总书记出席会议并发表重要讲话，深刻阐述人民代表大会制度具有的\n五个方面显著政治优势：（1）坚持中国共产党领导、保证党领导人民依法有效治理国家的\n显著优势，（2）践行全过程人民民主、保障人民…","sources":[{"id":"36adc9013d4bb8fe","label":"关于坚持和完善人民代表大会制度的重要思想","topic":"新时代中国特色社会主义思想","category":"非时政","text":"2024 年 9 月 14 日，中共中央、全国人大常委会隆重举行庆祝全国人民代表大会成立\n70 周年大会。习近平总书记出席会议并发表重要讲话，深刻阐述人民代表大会制度具有的\n五个方面显著政治优势：（1）坚持中国共产党领导、保证党领导人民依法有效治理国家的\n显著优势，（2）践行全过程人民民主、保障人民当家作主的显著优势，（3）贯彻民主集中\n制、保证国家政治生活既充满活力又安定有序的显著优势，（4）保障全面依法治国、实现\n国家各方面工作法治化的显著优势，（5）维护国家统一、保障国家长治久安的显著优势。\n同时，习近平总书记在会上系统总结新时代人民代表大会制度理论和实践创新重大成果，\n提出“八个必须坚持”：\n（1）必须坚持中国共产党领导，\n（2）必须坚持用制度体系保障人民\n当家作主，（3）必须坚持全面依法治国，（4）必须坚持民主集中制，（5）必须坚持走中国\n特色社会主义政治发展道路，（6）必须坚持推进国家治理体系和治理能力现代化，（7）必\n须坚持充分发挥人大代表作用，（8）必须坚持按照“四个机关”要求加强各级人大建设。\n（粉笔敲黑板：“四个机关”是指人民代表大会作为政治机关、国家权力机关、工作机\n关和代表机关的四重定位，体现了其政治属性、民主属性、法治属性和人民属性。）\n◎粉笔拓展\n1.国体，即国家性质\n我国宪法规定：“中华人民共和国是工人阶级领导的，以工农联盟为基础的人民民主专\n政的社会主义国家。”这是我国国体的明确规定。\n“社会主义制度是中华人民共和国的根本制\n度。”\n2.政体，即政权组织形式\n我国宪法规定：“中华人民共和国的一切权力属于人民。人民行使国家权力的机关是全\n国人民代表大会和地方各级人民代表大会。”也即，我国的政体是人民代表大会制度。","source":{"doc":"3ccc56f4000d1642c2d1","first":25,"last":26,"page":25,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-259adcd221f15b69":[]}};
